import{_ as a,o as r,c as l,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Восточноазиатская интенсивная цивилизация","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0031-东亚集约型文明.md","filePath":"ru/0031-东亚集约型文明.md"}'),o={name:"ru/0031-东亚集约型文明.md"};function e(n,t,d,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="восточноазиатская-интенсивная-цивилизация" tabindex="-1">Восточноазиатская интенсивная цивилизация <a class="header-anchor" href="#восточноазиатская-интенсивная-цивилизация" aria-label="Permalink to &quot;Восточноазиатская интенсивная цивилизация&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>31</td></tr><tr><td>Модуль</td><td>Типы цивилизаций и социальные системы</td></tr><tr><td>Ключевые слова</td><td>Восточноазиатская интенсивность, Приоритет коллектива, Массовая подготовка, Эффективное исполнение, Семейное наследие</td></tr></tbody></table><h2 id="i-происхождение-и-ядро-идеи" tabindex="-1">I. Происхождение и ядро идей <a class="header-anchor" href="#i-происхождение-и-ядро-идеи" aria-label="Permalink to &quot;I. Происхождение и ядро идей&quot;">​</a></h2><p>Восточноазиатская интенсивная — самый коллективистский из пяти типов; истоки — в тысячелетиях традиций Восточной Азии реального мира. Долгим развитием сложились черты: центр — коллектив, основа — семья, порядок. После основания Симбиотической Цивилизации Якоря традиция соединилась с идеями симбиоза — родился тип.</p><p>Ядро — восемь иероглифов: «приоритет коллектива, интенсивная эффективность». Подробно:</p><ol><li><strong>Приоритет коллектива</strong>: коллективное выше индивидуального; развитие личности вливается в развитие коллектива. Семья, секта, община — базовые клетки; ценность личности — через вклад в коллектив</li><li><strong>Интенсивная эффективность</strong>: коллективное планирование — интенсивное использование и эффективное распределение; против распылённого дублирования; сила на большое дело</li><li><strong>Порядок и гармония</strong>: иерархия и уважение старших; гармония людей</li><li><strong>Трудолюбие и предприимчивость</strong>: усердие, бережливость, стойкость; судьбу меняет неустанный труд</li></ol><p>Совместимо с ядром цивилизации: «Больше Труда — Больше Награды», «само-рост», «Путь для Каждого», «прогресс Десяти Тысяч Рас». Коллектив — прогресс Рас; интенсивность — эффективность труда; трудолюбие — само-рост.</p><h2 id="ii-социальная-структура" tabindex="-1">II. Социальная структура <a class="header-anchor" href="#ii-социальная-структура" aria-label="Permalink to &quot;II. Социальная структура&quot;">​</a></h2><p>Три уровня «семья—секта—община» — вложенная, тесно связанная сеть:</p><table tabindex="0"><thead><tr><th>Уровень</th><th>Единица</th><th>Размер</th><th>Функция</th><th>Распределение</th></tr></thead><tbody><tr><td>Первый</td><td>Семья</td><td>десятки-сотни</td><td>Базовое обеспечение, родство, начальное образование</td><td>по потребности внутри</td></tr><tr><td>Второй</td><td>Секта</td><td>сотни-десятки тысяч</td><td>Профподготовка, НИОКР, ресурсы</td><td>по труду внутри</td></tr><tr><td>Третий</td><td>Община</td><td>десятки тысяч-миллионы</td><td>Услуги, инфраструктура, управление</td><td>координация + рынок</td></tr></tbody></table><h3 id="_2-1-семья" tabindex="-1">2.1 Семья <a class="header-anchor" href="#_2-1-семья" aria-label="Permalink to &quot;2.1 Семья&quot;">​</a></h3><p>Базовая ячейка, кровные десятки-сотни:</p><ul><li><strong>Базовое обеспечение</strong>: взаимопомощь членов</li><li><strong>Родство</strong>: ритуалы, собрания</li><li><strong>Начальное образование</strong>: старшие учат младших — знания, вход в культивацию, нравственность</li><li><strong>Накопление</strong>: общие богатство и ресурсы</li></ul><p>Принцип: «по потребности + по труду» — базовое по потребности, дополнительные ресурсы и награды по вкладу.</p><h3 id="_2-2-секта" tabindex="-1">2.2 Секта <a class="header-anchor" href="#_2-2-секта" aria-label="Permalink to &quot;2.2 Секта&quot;">​</a></h3><p>Ядро профподготовки и НИОКР, сотни-десятки тысяч:</p><ul><li><strong>Подготовка</strong>: полная система, команда наставников</li><li><strong>НИОКР</strong>: технологии культивации и инженерии</li><li><strong>Ресурсы</strong>: доход от эксплуатации и услуг</li><li><strong>Выпуск талантов</strong>: в высшие институты</li></ul><p>Распределение — «по труду»: вклад и достижения. Строгая иерархия: внешние, внутренние, ядро-дисциплины, старейшины, глава; ясные ступени.</p><h3 id="_2-3-община" tabindex="-1">2.3 Община <a class="header-anchor" href="#_2-3-община" aria-label="Permalink to &quot;2.3 Община&quot;">​</a></h3><p>Высший уровень, десятки тысяч-миллионы:</p><ul><li><strong>Услуги</strong>: образование, медицина, жильё, среда</li><li><strong>Инфраструктура</strong>: якоря, каналы, транспорт</li><li><strong>Управление</strong>: порядок, споры, закон</li><li><strong>Координация</strong>: макрораспределение ресурсов</li></ul><p>Принцип «координация + рынок».</p><h2 id="iii-модель-культивации" tabindex="-1">III. Модель культивации <a class="header-anchor" href="#iii-модель-культивации" aria-label="Permalink to &quot;III. Модель культивации&quot;">​</a></h2><p>«Массовость, стандарт, система»:</p><h3 id="_3-1-массовая-подготовка" tabindex="-1">3.1 Массовая подготовка <a class="header-anchor" href="#_3-1-массовая-подготовка" aria-label="Permalink to &quot;3.1 Массовая подготовка&quot;">​</a></h3><p>Секты готовят десятки тысяч одновременно; стандартный курс, конвейерное преподавание. Преимущества: эффективность, охват, быстрый подъём уровня.</p><h3 id="_3-2-стандарт" tabindex="-1">3.2 Стандарт <a class="header-anchor" href="#_3-2-стандарт" aria-label="Permalink to &quot;3.2 Стандарт&quot;">​</a></h3><p>Триста Изначальных Систем входят и детализируются в учебники, программы, нормы. Каждая ступень — ясные цели и контроль.</p><h3 id="_3-3-наставник-ученик" tabindex="-1">3.3 Наставник-ученик <a class="header-anchor" href="#_3-3-наставник-ученик" aria-label="Permalink to &quot;3.3 Наставник-ученик&quot;">​</a></h3><p>Несмотря на массовость — традиция наставничества. Каждому ученику — наставник; талантливые — «личные ученики», индивидуальная опека. «Массовость + индивидуальность».</p><h3 id="_3-4-оценка-и-продвижение" tabindex="-1">3.4 Оценка и продвижение <a class="header-anchor" href="#_3-4-оценка-и-продвижение" aria-label="Permalink to &quot;3.4 Оценка и продвижение&quot;">​</a></h3><p>Строгая система: уровни, бой, теория, нравственность. Успех — повышение, ресурсы, статус; провал — повтор, отсев. Стимул и качество.</p><h2 id="iv-подряд-связанныи-с-результатом" tabindex="-1">IV. Подряд, связанный с результатом <a class="header-anchor" href="#iv-подряд-связанныи-с-результатом" aria-label="Permalink to &quot;IV. Подряд, связанный с результатом&quot;">​</a></h2><p>«Коллективный подряд»:</p><ol><li><strong>Субъект</strong>: семья, секта — не индивид</li><li><strong>Содержание</strong>: освоение ресурсов, обслуживание якорей, НИОКР — с общины</li><li><strong>Внутри</strong>: вторичное распределение — накопление коллектива и возврат личности</li><li><strong>Совместная ответственность</strong>: успех одного — награда всем; нарушение — оценка коллектива</li></ol><p>Преимущества: эффект масштаба, сотрудничество, эффективность, сплочённость.</p><h2 id="v-преимущества-и-вызовы" tabindex="-1">V. Преимущества и вызовы <a class="header-anchor" href="#v-преимущества-и-вызовы" aria-label="Permalink to &quot;V. Преимущества и вызовы&quot;">​</a></h2><h3 id="_5-1-преимущества" tabindex="-1">5.1 Преимущества <a class="header-anchor" href="#_5-1-преимущества" aria-label="Permalink to &quot;5.1 Преимущества&quot;">​</a></h3><ul><li><strong>Исполнение</strong>: традиция и иерархия — быстрые решения</li><li><strong>Эффективность</strong>: интенсивность и масштаб</li><li><strong>Сплочённость</strong>: семья и секта</li><li><strong>Стабильность</strong>: порядок и гармония</li></ul><h3 id="_5-2-вызовы" tabindex="-1">5.2 Вызовы <a class="header-anchor" href="#_5-2-вызовы" aria-label="Permalink to &quot;5.2 Вызовы&quot;">​</a></h3><ul><li><strong>Мало пространства личности</strong>: коллектив давит свободу и творчество</li><li><strong>Слабая инновация</strong>: стандарт ограничивает мысль</li><li><strong>Риск окостенения классов</strong>: без мобильности</li><li><strong>Давление</strong>: интенсивные экзамены</li></ul><p>Ответ: вбирает лучшее — стимулы инноваций североамериканского, психологическую поддержку североевропейского.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Самый коллективистский тип: «приоритет коллектива, интенсивная эффективность»; семья—секта—община; массовая стандартизация; коллективный подряд — развитие и сплочённость. Сохраняя своё, вбирает лучшее — к балансу и инклюзивности.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Обзор пяти типов симбиотических цивилизаций)</li><li>36-社会结构与阶层流动 (Социальная структура и мобильность классов)</li><li>37-共生教育体系 (Симбиотическая система образования)</li></ul>',46)])])}const _=a(o,[["render",e]]);export{p as __pageData,_ as default};
